mapper.select:
SELECT CHECK_ID AS "checkId", CHECK_NO AS "checkNumber", CHECK_NAME AS "checkName", CHECK_TYPE AS "checkType", CHECK_TYPE_NAME AS "checkTypeName", WAREHOUSE_ID AS "warehouseId", WAREHOUSE_NAME AS "warehouseName", INVENTORY_COUNT AS "inventoryCount", CHECK_PROGRESS AS "checkProgress", VARIANCE_AMOUNT AS "varianceAmount", CASE CHECK_STATUS WHEN 0 THEN 'PLANNING' WHEN 1 THEN 'CHECKING' WHEN 2 THEN 'COMPLETED' WHEN 3 THEN 'APPROVED' WHEN 4 THEN 'CANCELLED' ELSE 'UNKNOWN' END AS "status", TO_CHAR(CHECK_DATE, 'YYYY-MM-DD') AS "checkDate", APPROVER_NAME AS "operatorName", DESCRIPTION AS "description", TO_CHAR(CREATE_TIME, 'YYYY-MM-DD HH24:MI:SS') AS "createTime" FROM TBL_INVENTORY_CHECK WHERE DELETED = 0
AND TENANT_ID = #{param.tenantId}
AND CHECK_NO LIKE '%' || #{param.checkNumber} || '%'
AND CHECK_TYPE = #{param.checkType}
AND CHECK_STATUS = CASE #{param.status} WHEN 'PLANNING' THEN 0 WHEN 'CHECKING' THEN 1 WHEN 'COMPLETED' THEN 2 WHEN 'APPROVED' THEN 3 WHEN 'CANCELLED' THEN 4 ELSE -1 END
AND WAREHOUSE_ID = #{param.warehouseId}
AND CHECK_DATE >= TO_DATE(#{param.startDate}, 'YYYY-MM-DD')
AND CHECK_DATE <= TO_DATE(#{param.endDate}, 'YYYY-MM-DD')
ORDER BY CREATE_TIME DESC

SELECT * FROM TBL_INVENTORY_CHECK
WHERE CHECK_NO = #{checkNo}
AND TENANT_ID = #{tenantId}
AND DELETED = 0

SELECT * FROM TBL_INVENTORY_CHECK
WHERE CHECK_TYPE = #{checkType}
AND TENANT_ID = #{tenantId}
AND DELETED = 0
ORDER BY CREATE_TIME DESC

SELECT * FROM TBL_INVENTORY_CHECK
WHERE CHECK_STATUS = #{checkStatus}
AND TENANT_ID = #{tenantId}
AND DELETED = 0
ORDER BY CREATE_TIME DESC

SELECT * FROM TBL_INVENTORY_CHECK
WHERE WAREHOUSE_ID = #{warehouseId}
AND TENANT_ID = #{tenantId}
AND DELETED = 0
ORDER BY CREATE_TIME DESC

